       (55, 'customer', 'wallet_recharge_email_to_customer', 'Wallet Recharge Confirmation',
        'Your Wallet Has Been Recharged on [[store_name]]',
        '<span id=\"docs-internal-guid-b30785bd-7fff-1e0b-e705-8fd54008f465\">\r\n  <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\">\r\n    <span style=\"font-size: 11pt; font-family: Roboto, sans-serif; font-weight: 700; background-color: transparent; vertical-align: baseline;\">Dear [[customer_name]],</span>\r\n  </p>\r\n  \r\n  <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\">\r\n    <span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; vertical-align: baseline;\">\r\n      This is to confirm that your wallet has been successfully recharged.\r\n    </span>\r\n  </p>\r\n\r\n  <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\">\r\n    <span style=\"font-size: 11pt; font-family: Roboto, sans-serif; font-weight: 700; background-color: transparent; vertical-align: baseline;\">Payment Details:</span>\r\n  </p>\r\n\r\n  <ul style=\"margin-bottom: 0px; padding-inline-start: 48px;\">\r\n    <li dir=\"ltr\" style=\"list-style-type: disc; font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\" aria-level=\"1\">\r\n      <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:0pt;\" role=\"presentation\">\r\n        <span style=\"font-size: 11pt; font-weight: 700;\">Payment Date:</span>\r\n        <span> [[date]]</span>\r\n      </p>\r\n    </li>\r\n    <li dir=\"ltr\" style=\"list-style-type: disc; font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\" aria-level=\"1\">\r\n      <p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom:0pt;\" role=\"presentation\">\r\n        <span style=\"font-size: 11pt; font-weight: 700;\">Amount Rechaged:</span>\r\n        <span> [[amount]]</span>\r\n      </p>\r\n    </li>\r\n    <li dir=\"ltr\" style=\"list-style-type: disc; font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\" aria-level=\"1\">\r\n      <p dir=\"ltr\" style=\"line-height:1.38;margin-top:0pt;margin-bottom:12pt;\" role=\"presentation\">\r\n        <span style=\"font-size: 11pt; font-weight: 700;\">Payment Method:</span>\r\n        <span> [[payment_method]]</span>\r\n      </p>\r\n    </li>\r\n  </ul>\r\n\r\n  <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\">\r\n    <span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; vertical-align: baseline;\">\r\n      If you have any questions or need assistance, feel free to contact us at [[admin_email]].\r\n    </span>\r\n  </p>\r\n\r\n  <p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\">\r\n    <span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; vertical-align: baseline;\">\r\n      Best regards,<br>\r\n      The [[store_name]] Team\r\n    </span>\r\n  </p>\r\n</span>',
        1, 0, 1, NULL, '2025-06-03 16:05:23', '2025-06-03 16:05:23'),
       (56, 'seller', 'email_update_verification_seller', 'Email Update Verification',
        'Verify Your New Email Address for Your [[store_name]] Seller Account',
        '<span id=\"docs-internal-guid-update-seller\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; font-weight: 700;\">Dear [[seller_name]],</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">We received a request to change the email address associated with your seller account on [[store_name]].</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">To verify your new email address and complete the update, please click the link below:</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">[[verify_email_button]]</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">If you did not request this change, you can safely ignore this email.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">For any assistance, contact us at </span><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; font-weight: 700;\">[[admin_email]]</span><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">Thank you,</span><br><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">The [[store_name]] Team</span></p></span>',
        1, 0, 1, NULL, '2025-07-09 13:42:01', '2025-07-09 13:42:01'),
       (57, 'customer', 'email_update_verification_customer', 'Email Update Verification',
        'Confirm Your New Email Address for [[store_name]]',
        '<span id=\"docs-internal-guid-update-customer\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; font-weight: 700;\">Dear [[customer_name]],</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">We received a request to change the email address associated with your [[store_name]] account.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">To verify your new email address and complete the update, please click the link below:</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">[[verify_email_button]]</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">If you did not request this change, you can safely ignore this email.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">Should you have any questions or need assistance, feel free to reach out to our support team at </span><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent; font-weight: 700;\">[[admin_email]]</span><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">Thank you,</span><br><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; background-color: transparent;\">The [[store_name]] Team</span></p></span>',
        1, 0, 1, NULL, '2025-07-09 13:42:01', '2025-07-09 13:42:01'),
       (58, 'customer', 'change_email_verification_code_customer', 'Verification Code for Email Update',
        'Verify Your New Email Address on [[store_name]]',
        '<span id=\"docs-internal-guid-update-verification-code-customer\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; font-weight: 700;\">Dear [[customer_name]],</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">We received a request to change the email address associated with your [[store_name]] account.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">To confirm this change, please use the Code sent below:</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 14pt; font-family: Roboto, sans-serif; font-weight: bold;\">[[code]]</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">This Code is for verifying your new email: <strong>[[new_email]]</strong></span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">If you did not request this, please ignore the email or contact support.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">For any questions, contact us at <strong>[[admin_email]]</strong></span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">Thank you,<br>The [[store_name]] Team</span></p></span>',
        1, 0, 1, NULL, '2025-07-09 13:42:01', '2025-07-09 13:42:01'),
       (59, 'seller', 'change_email_verification_code_seller', 'Verification Code for Email Update Verification',
        'Verify Your New Email Address on [[store_name]]',
        '<span id=\"docs-internal-guid-update-verification-code-seller\"><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif; font-weight: 700;\">Dear [[seller_name]],</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">We received a request to change the email address associated with your seller account on [[store_name]].</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">To confirm this change, please use the Code sent below:</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 14pt; font-family: Roboto, sans-serif; font-weight: bold;\">[[code]]</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">This Code is for verifying your new email: <strong>[[new_email]]</strong></span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">If you did not request this, please ignore the email or contact support.</span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">For any questions, contact us at <strong>[[admin_email]]</strong></span></p><p dir=\"ltr\" style=\"line-height:1.38;margin-top:12pt;margin-bottom:12pt;\"><span style=\"font-size: 11pt; font-family: Roboto, sans-serif;\">Thank you,<br>The [[store_name]] Team</span></p></span>',
        1, 0, 1, NULL, '2025-07-09 13:42:01', '2025-07-09 13:42:01'),
